<?php
require __DIR__.'/../includes/core.php';require_login(['admin']);$error='';
$cycles=all('SELECT c.id,c.term,s.name session_name FROM evaluation_cycles c JOIN academic_sessions s ON s.id=c.session_id ORDER BY c.id DESC');$modules=all('SELECT id,name FROM modules ORDER BY id');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{
 $action=(string)($_POST['action']??'');if($action==='create'){
  $cycle=(int)($_POST['cycle_id']??0);$module=(int)($_POST['module_id']??0);
  if($cycle&&!one('SELECT id FROM evaluation_cycles WHERE id=?',[$cycle]))throw new Exception('Invalid cycle');
  if($module&&!one('SELECT id FROM modules WHERE id=?',[$module]))throw new Exception('Invalid module');
  $token=bin2hex(random_bytes(32));sql('INSERT INTO evaluation_bulk_shares(token_hash,created_by,cycle_id,module_id,expires_at) VALUES (?,?,?,?,DATE_ADD(NOW(),INTERVAL 7 DAY))',[hash('sha256',$token),me()['id'],$cycle?:null,$module?:null]);
  $_SESSION['bulk_share_link']=url('external/all_reviews.php?token='.$token);audit('bulk_external_share_created','Cycle '.$cycle.' module '.$module);go('admin/external_access.php');
 }elseif($action==='revoke'){sql('UPDATE evaluation_bulk_shares SET revoked_at=NOW() WHERE id=?',[(int)($_POST['share_id']??0)]);audit('bulk_external_share_revoked',(string)($_POST['share_id']??''));flash('Link revoked.');go('admin/external_access.php');}
 }catch(Throwable $e){$error=$e->getMessage();}}
$shares=all('SELECT bs.*,c.term,s.name session_name,m.name module_name FROM evaluation_bulk_shares bs LEFT JOIN evaluation_cycles c ON c.id=bs.cycle_id LEFT JOIN academic_sessions s ON s.id=c.session_id LEFT JOIN modules m ON m.id=bs.module_id ORDER BY bs.id DESC LIMIT 100');
ob_start();?><div class="card"><h2>One external assessor link for all reports</h2><p>The link allows its holder to view all submitted reports within the chosen scope and leave one remark per report. It expires after 7 days and can be revoked. Share only with authorized assessors; anyone with the link can see confidential reports.</p><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><?php if(!empty($_SESSION['bulk_share_link'])):$link=$_SESSION['bulk_share_link'];unset($_SESSION['bulk_share_link']);?><p><strong>Copy this link now (shown once):</strong></p><input readonly onclick="this.select()" value="<?=h($link)?>"><?php endif;?><form method="post"><?=token()?><input type="hidden" name="action" value="create"><label>Academic cycle</label><select name="cycle_id"><option value="0">All academic cycles</option><?php foreach($cycles as $c):?><option value="<?=$c['id']?>"><?=h($c['session_name'].' '.$c['term'])?></option><?php endforeach;?></select><label>Module</label><select name="module_id"><option value="0">All evaluation modules</option><?php foreach($modules as $m):?><option value="<?=$m['id']?>"><?=h($m['name'])?></option><?php endforeach;?></select><p><button>Create one general review link</button></p></form></div><div class="card"><h3>Manage general links</h3><div class="tablewrap"><table><tr><th>Scope</th><th>Expiry</th><th>Status</th><th>Action</th></tr><?php foreach($shares as $s):?><tr><td><?=h(($s['session_name']??'All cycles').' '.($s['term']??'').' / '.($s['module_name']??'All modules'))?></td><td><?=h($s['expires_at'])?></td><td><?=$s['revoked_at']?'Revoked':(strtotime($s['expires_at'])<time()?'Expired':'Active')?></td><td><?php if(!$s['revoked_at']):?><form method="post"><?=token()?><input type="hidden" name="action" value="revoke"><input type="hidden" name="share_id" value="<?=$s['id']?>"><button>Revoke</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php layout('General external assessor links',ob_get_clean());
